// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint128 amountA, uint128 amountB, address actor) public {
        vm.assume(amountA <= VALUE_CAP);
        vm.assume(amountB <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(uint256(amountA) + uint256(amountB) > uint256(amountA) && uint256(amountA) + uint256(amountB) >= amountA);

        uint256 total = uint256(amountA) + uint256(amountB);

        vm.deal(actor, total);
        vm.startPrank(actor);
        c.Put{value: amountA}(0);
        c.Put{value: amountB}(0);
        vm.stopPrank();

        (uint256 unlockTime, uint256 balance) = c.Acc(actor);
        unlockTime; // observable surface: public Acc getter

        // General rule: the stored balance is exactly the accumulated deposit total.
        assertTrue(balance == total);
    }
}
